#!/usr/bin/env roundup

describe "roundup(1) testing of Arch Linux packages"

p=$(dirname "$BASH_SOURCE")/../pkg-diff.sh
o=$(dirname "$BASH_SOURCE")/../same-build-result.sh

# Build tiny makepkg-style archives without requiring pacman or fakeroot.
arch_pkg() (
    local dest=$1 name=$2 version=$3 arch=$4 ext=$5
    local stage
    stage=$(mktemp -d "$roundup_tmp/stage.XXXXXXXX")
    mkdir -p "$dest" "$stage/usr/bin"
    cat > "$stage/.PKGINFO" <<EOF
# Generated by makepkg $build
pkgname = $name
pkgbase = demo
pkgver = $version
pkgdesc = comparison fixture
builddate = $build
packager = builder $build
size = $build
arch = $arch
provides = demo-tool=$version
depend = demo-libs=${version%-*}
depend = fixed=1.0+g123
depend = ${dependency:-sh}
EOF
    printf 'installed = tool-%s-any\n' "$build" > "$stage/.BUILDINFO"
    printf '#mtree\n./.PKGINFO time=%s\n' "$build" | gzip -n > "$stage/.MTREE"
    printf '%s\n' "${payload:-hello world}" > "$stage/usr/bin/hello world"
    printf 'documentation\n' | gzip -n "$compression" > "$stage/usr/bin/message.gz"
    chmod "${mode:-755}" "$stage/usr/bin/hello world"
    ln -s "${target:-absent}" "$stage/usr/bin/link"
    printf '%s\n' "${install:-:}" > "$stage/.INSTALL"
    tar --mtime="@$build" --owner=0 --group=0 -caf \
        "$dest/$name-$version-$arch.pkg.tar$ext" -C "$stage" .
)

root=$(mktemp -d "$roundup_tmp/arch.XXXXXXXX")
old="$root/old-set"
new="$root/new-set"
build=1700000000
compression=-1
arch_pkg "$old" demo-tool 1.0+g123-1 x86_64 .zst
arch_pkg "$old" demo-data 1.0+g123-1 any .zst
build=1700000100
compression=-9
arch_pkg "$new" demo-tool 1.1+g234-2 x86_64 .xz
arch_pkg "$root/data" demo-data 1.1+g234-2 any ''
touch "$new/demo-tool-1.1+g234-2-x86_64.pkg.tar.xz.sig"

it_pairs_split_packages_across_rebuilds_and_compressions()
{
    "$o" "$old" "$new" "$root/data"
}

it_reports_missing_and_replaced_subpackages()
{
    if out=$("$o" "$old" "$new"); then return 1; fi
    grep -F 'different number of subpackages' <<< "$out"
    arch_pkg "$root/other" demo-data 1.1+g234-2 x86_64 .gz
    if out=$("$o" "$old" "$new" "$root/other"); then return 1; fi
    grep -F '(name, arch) tuples differs' <<< "$out"
}

it_compares_metadata_and_payload_with_check_all()
{
    payload='changed payload' dependency='bash>=5' \
        arch_pkg "$root/changed" demo-tool 1.0+g123-1 x86_64 .zst
    if out=$("$o" -a "$old" "$root/changed" "$root/data"); then return 1; fi
    grep -Fx '+depend = bash>=5' <<< "$out"
    grep -Fx '+changed payload' <<< "$out"
    grep -Fx 'binaries_differ' <<< "$out"
}

it_treats_install_script_changes_as_significant()
{
    install='post_install() { echo changed; }' \
        arch_pkg "$root/script" demo-tool 1.0+g123-1 x86_64 .zst
    if out=$("$p" "$old"/demo-tool-* "$root/script"/*); then return 1; fi
    grep -Fx '+post_install() { echo changed; }' <<< "$out"
}

it_detects_mode_and_dangling_symlink_changes()
{
    mode=644 target=also-absent arch_pkg "$root/attrs" demo-tool 1.0+g123-1 x86_64 .zst
    if out=$("$p" "$old"/demo-tool-* "$root/attrs"/*); then return 1; fi
    grep -F '+-rw-r--r-- 0/0 "usr/bin/hello world"' <<< "$out"
    grep -F '"usr/bin/link" -> "also-absent"' <<< "$out"
}

it_rejects_invalid_archives_even_with_check_all()
{
    local bad="$root/bad.pkg.tar"
    tar -cf "$bad" --files-from /dev/null
    if out=$("$p" -a "$bad" "$bad"); then return 1; fi
    grep -F 'missing or invalid .PKGINFO' <<< "$out"
    printf 'not a tar file\n' > "$bad"
    ! "$p" -a "$bad" "$bad" || return 1
}

it_rejects_an_extraction_error_on_either_side()
{
    local good="$new/demo-tool-1.1+g234-2-x86_64.pkg.tar.xz"
    local bad="$root/truncated.pkg.tar.xz"
    # With only the xz footer truncated, all tar members are still readable.
    head -c -1 "$good" > "$bad"
    ! "$p" -a "$bad" "$good" || return 1
    ! "$p" -a "$good" "$bad" || return 1
}
